pub fn parse_g0_tokens_remain_diagnostic_at(tokens: Rc<Vec<Rc<Token>>>, furthest: Rc<ParseFurthestFailure>) -> Rc<Diagnostic> {
    match v1_rt::list_get_optional(&tokens, 0) {
    std::option::Option::None => parse_g0_tokens_remain_diagnostic(tokens.clone()),
    Some(first) => match (*furthest.clone()).clone() {
    ParseFurthestFailure::FurthestNone => parse_g0_tokens_remain_diagnostic(tokens.clone()),
    ParseFurthestFailure::FurthestAtToken { token: tok, expectation, .. } => if (tok.start.clone() > first.start.clone()) {
        match expectation.clone() {
    Some(reason) => match parse_token_before(tokens.clone(), tok.start.clone()) {
    Some(anchor) => parse_expectation_diagnostic(reason.clone(), anchor.clone()),
    std::option::Option::None => parse_g0_tokens_remain_diagnostic(Rc::new(vec![tok.clone()])),
},
    std::option::Option::None => parse_g0_tokens_remain_diagnostic(Rc::new(vec![tok.clone()])),
}
    } else {
        parse_g0_tokens_remain_diagnostic(tokens.clone())
    },
    ParseFurthestFailure::FurthestAtEnd { expectation: expectation, .. } => match v1_rt::list_get_optional(&tokens, v1_rt::int_sub(crate::std_algebra::length(tokens.clone()), 1)) {
    std::option::Option::None => parse_g0_tokens_remain_diagnostic(tokens.clone()),
    Some(last) => match expectation.clone() {
    Some(reason) => parse_expectation_diagnostic(reason.clone(), last.clone()),
    std::option::Option::None => parse_g0_tokens_remain_diagnostic(Rc::new(vec![Rc::new(Token {
    class: last.class.clone(),
    lexeme: last.lexeme.clone(),
    file: last.file.clone(),
    start: last.end.clone(),
    end: last.end.clone(),
})])),
},
},
},
}
}

