pub fn parse_expectation_first(left: Option<ParseRefusalReason>, right: Option<ParseRefusalReason>) -> Option<ParseRefusalReason> {
    match left.clone() {
    Some(_) => left.clone(),
    std::option::Option::None => right,
}
}

pub fn parse_furthest_join(left: Rc<ParseFurthestFailure>, right: Rc<ParseFurthestFailure>) -> Rc<ParseFurthestFailure> {
    match (*left.clone()).clone() {
    ParseFurthestFailure::FurthestNone => right.clone(),
    ParseFurthestFailure::FurthestAtEnd { expectation: le, .. } => match (*right.clone()).clone() {
    ParseFurthestFailure::FurthestNone => left.clone(),
    ParseFurthestFailure::FurthestAtToken { .. } => left.clone(),
    ParseFurthestFailure::FurthestAtEnd { expectation: re, .. } => Rc::new(ParseFurthestFailure::FurthestAtEnd {
    expectation: parse_expectation_first(le.clone(), re.clone()),
}),
},
    ParseFurthestFailure::FurthestAtToken { token: lt, expectation: le, .. } => match (*right.clone()).clone() {
    ParseFurthestFailure::FurthestNone => left.clone(),
    ParseFurthestFailure::FurthestAtEnd { expectation: _, .. } => right.clone(),
    ParseFurthestFailure::FurthestAtToken { token: rt, expectation: re, .. } => if (rt.start.clone() > lt.start.clone()) {
        right.clone()
    } else {
        if (rt.start.clone() == lt.start.clone()) {
            Rc::new(ParseFurthestFailure::FurthestAtToken {
    token: lt.clone(),
    expectation: parse_expectation_first(le.clone(), re.clone()),
})
        } else {
            left.clone()
        }
    },
},
}
}

pub fn parse_furthest_at(tokens: Rc<Vec<Rc<Token>>>) -> Rc<ParseFurthestFailure> {
    match parse_token_first(tokens) {
    Some(tok) => Rc::new(ParseFurthestFailure::FurthestAtToken {
    token: tok.clone(),
    expectation: std::option::Option::None,
}),
    std::option::Option::None => Rc::new(ParseFurthestFailure::FurthestAtEnd {
    expectation: std::option::Option::None,
}),
}
}

pub fn parse_furthest_expected_at(tokens: Rc<Vec<Rc<Token>>>, reason: ParseRefusalReason) -> Rc<ParseFurthestFailure> {
    match parse_token_first(tokens) {
    Some(tok) => Rc::new(ParseFurthestFailure::FurthestAtToken {
    token: tok.clone(),
    expectation: Some(reason.clone()),
}),
    std::option::Option::None => Rc::new(ParseFurthestFailure::FurthestAtEnd {
    expectation: Some(reason.clone()),
}),
}
}

