#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum FirstKey {
    FirstAnyOfClass {
        token_class: Symbol,
    },
    FirstExactWord {
        token_class: Symbol,
        lexeme: Symbol,
    },
}
impl FirstKey {
    pub fn token_class(&self) -> Symbol {
        match self {
            FirstKey::FirstAnyOfClass { token_class: __val, .. } => __val.clone(),
            FirstKey::FirstExactWord { token_class: __val, .. } => __val.clone(),
        }
    }
}

pub fn first_key_class(key: Rc<FirstKey>) -> std::string::String {
    match (*key.clone()).clone() {
    FirstKey::FirstAnyOfClass { token_class: c, .. } => c.clone(),
    FirstKey::FirstExactWord { token_class: c, .. } => c.clone(),
}
}

pub fn first_key_eq(left: Rc<FirstKey>, right: Rc<FirstKey>) -> bool {
    match (*left.clone()).clone() {
    FirstKey::FirstAnyOfClass { token_class: lc, .. } => match (*right.clone()).clone() {
    FirstKey::FirstAnyOfClass { token_class: rc, .. } => (lc.clone() == rc.clone()),
    FirstKey::FirstExactWord { .. } => false,
},
    FirstKey::FirstExactWord { token_class: lc, lexeme: lw, .. } => match (*right.clone()).clone() {
    FirstKey::FirstExactWord { token_class: rc, lexeme: rw, .. } => ((lc.clone() == rc.clone()) && (lw.clone() == rw.clone())),
    FirstKey::FirstAnyOfClass { token_class: _, .. } => false,
},
}
}

pub fn first_key_overlaps(left: Rc<FirstKey>, right: Rc<FirstKey>) -> bool {
    if (first_key_class(left.clone()) == first_key_class(right.clone())) {
        match (*left.clone()).clone() {
    FirstKey::FirstAnyOfClass { token_class: _, .. } => true,
    FirstKey::FirstExactWord { lexeme: lw, .. } => match (*right.clone()).clone() {
    FirstKey::FirstAnyOfClass { token_class: _, .. } => true,
    FirstKey::FirstExactWord { lexeme: rw, .. } => (lw.clone() == rw.clone()),
},
}
    } else {
        false
    }
}

pub fn first_key_admits_word(key: Rc<FirstKey>, token_class: std::string::String, word: String) -> bool {
    match (*key.clone()).clone() {
    FirstKey::FirstAnyOfClass { token_class: c, .. } => (c.clone() == token_class.clone()),
    FirstKey::FirstExactWord { token_class: c, lexeme: w, .. } => ((c.clone() == token_class.clone()) && (v1_rt::symbol_lexeme(w.clone()) == word.clone())),
}
}

