pub fn parse_expr_repeat_step(mut __tco_loop_element: Rc<PreparedGrammarExpr>, mut __tco_loop_all_tokens: Rc<Vec<Rc<Token>>>, mut __tco_loop_root: Rc<GrammarRoot>, mut __tco_loop_acc: Rc<ParseRepeatAcc>) -> Rc<ParseRepeatAcc> {
    { loop {
        #[allow(unused_mut)]
        let mut element = __tco_loop_element;
        #[allow(unused_mut)]
        let mut all_tokens = __tco_loop_all_tokens;
        #[allow(unused_mut)]
        let mut root = __tco_loop_root;
        #[allow(unused_mut)]
        let mut acc = __tco_loop_acc;
        if acc.done.clone() {
            break acc.clone();
} else {
            match (*parse_expr_with_first(element.clone(), acc.remaining.clone(), all_tokens.clone(), root.clone(), (*acc.table).clone(), acc.prov.clone())).clone() {
    ParseExprResult::ParseExprRejected { table: ref __rc_table, .. } => { let table1 = __rc_table.as_ref(); break Rc::new(ParseRepeatAcc {
    remaining: acc.remaining.clone(),
    acc_nodes: acc.acc_nodes.clone(),
    acc_diags: acc.acc_diags.clone(),
    done: true,
    prov: acc.prov.clone(),
    table: Box::new(table1.clone()),
}); },
    ParseExprResult::ParseExprAccepted { remaining: rest, captured: cap, diagnostics: diags, prov: prov1, table: ref __rc_table, .. } => { let table1 = __rc_table.as_ref(); match (parse_current_position(rest.clone()) != parse_current_position(acc.remaining.clone())) {
    true => { {
                let __tco_0 = element;
let __tco_1 = all_tokens;
let __tco_2 = root;
let __tco_3 = Rc::new(ParseRepeatAcc {
    remaining: rest.clone(),
    acc_nodes: Rc::new({ let mut __cons_v = (*acc.acc_nodes.clone()).clone(); __cons_v.insert(0, cap.clone()); __cons_v }),
    acc_diags: Rc::new({ let mut __cons_v = (*acc.acc_diags.clone()).clone(); __cons_v.insert(0, diags.clone()); __cons_v }),
    done: false,
    prov: prov1.clone(),
    table: Box::new(table1.clone()),
});
__tco_loop_element = __tco_0;
__tco_loop_all_tokens = __tco_1;
__tco_loop_root = __tco_2;
__tco_loop_acc = __tco_3;
continue;
} },
    false => { break Rc::new(ParseRepeatAcc {
    remaining: acc.remaining.clone(),
    acc_nodes: acc.acc_nodes.clone(),
    acc_diags: acc.acc_diags.clone(),
    done: true,
    prov: acc.prov.clone(),
    table: Box::new(table1.clone()),
}); },
} },
}
}
} }
}

pub fn parse_expr_repeat(element: Rc<PreparedGrammarExpr>, tokens: Rc<Vec<Rc<Token>>>, all_tokens: Rc<Vec<Rc<Token>>>, root: Rc<GrammarRoot>, table: ParseTable, prov: Rc<ParseProvenanceState>) -> Rc<ParseExprResult> {
    {
        let init = Rc::new(ParseRepeatAcc {
    remaining: tokens.clone(),
    acc_nodes: Rc::new(vec![]),
    acc_diags: Rc::new(vec![]),
    done: false,
    prov: prov.clone(),
    table: Box::new(table.clone()),
});
let result = parse_expr_repeat_step(element, all_tokens, root, init);
let stamped = parse_stamp_derived_repeat(crate::std_algebra::list_reverse(result.acc_nodes.clone()), result.prov.clone());
Rc::new(ParseExprResult::ParseExprAccepted {
    remaining: result.remaining.clone(),
    captured: stamped.node.clone(),
    diagnostics: parse_flatten_diag_batches(crate::std_algebra::list_reverse(result.acc_diags.clone())),
    prov: stamped.prov.clone(),
    table: Box::new((*result.table).clone()),
})
}
}

