pub fn parse_token_start_order_violation(tokens: Rc<Vec<Rc<Token>>>) -> Option<Rc<Token>> {
    crate::std_algebra::fold_list(tokens, Rc::new(ParseStartOrderAcc {
    previous: crate::std_optional::optional_absent(),
    violation: crate::std_optional::optional_absent(),
}), |acc, tok| match acc.violation.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => match acc.previous.clone() {
    Some(prev) => if (tok.start.clone() > prev.start.clone()) {
        Rc::new(ParseStartOrderAcc {
    previous: crate::std_optional::optional_present(tok.clone()),
    violation: crate::std_optional::optional_absent(),
})
    } else {
        Rc::new(ParseStartOrderAcc {
    previous: crate::std_optional::optional_present(tok.clone()),
    violation: crate::std_optional::optional_present(tok.clone()),
})
    },
    std::option::Option::None => Rc::new(ParseStartOrderAcc {
    previous: crate::std_optional::optional_present(tok.clone()),
    violation: crate::std_optional::optional_absent(),
}),
},
}).violation.clone()
}

