pub fn parse_production_run(tokens: Rc<Vec<Rc<Token>>>, validated: Rc<ValidatedGrammarRoot>, analysis: Rc<GrammarFirstAnalysis>, production_name: std::string::String, seed: OccurrenceIdAllocator, layout: Option<Rc<StreamLayout>>) -> Rc<ProductionRun> {
    match parse_token_start_order_violation(tokens.clone()) {
    Some(tok) => Rc::new(ProductionRun::ProductionRunRefused {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(parse_refusal_reason_diagnostic(ParseRefusalReason::TokenStartsNotIncreasing, tok.file.clone(), tok.start.clone(), tok.end.clone())),
}),
    std::option::Option::None => {
        let root = validated.root.clone();
let table = parse_table_for_stream_analyzed(validated.clone(), analysis, tokens.clone(), layout);
match (*grammar_lookup_production_indexed(table.clone(), production_name)).clone() {
    Witness::Holds { value: production, .. } => {
            let prov = parse_prov_seeded(seed);
let parsed = parse_expr_with_first(parse_table_prepared_expr(table.clone(), production.clone()), tokens.clone(), tokens.clone(), root.clone(), table.clone(), prov);
match parse_expr_result_table(parsed.clone()).refusal.clone() {
    Some(refusal) => Rc::new(ProductionRun::ProductionRunRefused {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(refusal.clone()),
}),
    std::option::Option::None => Rc::new(ProductionRun::ProductionRunParsed {
    parsed: parsed.clone(),
    production: production.clone(),
    root: root.clone(),
}),
}
},
    Witness::Violates { diagnostic: d, .. } => Rc::new(ProductionRun::ProductionRunRefused {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
}
},
}
}

